CREATE TABLE users (
	id VARCHAR(64) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	pw_salt VARCHAR(32) NOT NULL, 
	pw_hash VARCHAR(64) NOT NULL, 
	avatar VARCHAR(32) NOT NULL, 
	color VARCHAR(16) NOT NULL, 
	created BIGINT NOT NULL, 
	name_key VARCHAR(80) NOT NULL, 
	PRIMARY KEY (id)
);
INSERT INTO "users" VALUES('u-c9cd2c97f8f0','旧鸭🦆','743eba430470eef5f053979edf61883a','f525f2864bfbd35bf417b7677fb2ab43811dacb4edbb8f4dd5ffbce27a8cd97d','🦆','#ff7a59',1793121062033,'旧鸭🦆');
CREATE TABLE works (
	id VARCHAR(64) NOT NULL, 
	user_id VARCHAR(64) NOT NULL, 
	title TEXT NOT NULL, 
	description TEXT NOT NULL, 
	design TEXT NOT NULL, 
	provenance TEXT, 
	parent_id VARCHAR(64), 
	scheme_id VARCHAR(64), 
	created BIGINT NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);
CREATE UNIQUE INDEX users_name_key ON users (name_key);
CREATE INDEX schemes_user ON schemes (user_id, updated);
CREATE INDEX works_parent ON works (parent_id);
CREATE INDEX works_created ON works (created, id);
CREATE INDEX works_user_created ON works (user_id, created, id);
COMMIT;
